// with_named_replies loads `replies` as `configure` says into
// `named_replies[name]`, besides any other load of it.
pub fn (q CommentQuery) with_named_replies(name string, configure ...fn (CommentQuery) CommentQuery) CommentQuery {
	mut next := q
	mut named := q.named_replies.clone()
	named[name] = configure
	next.named_replies = named
	return next
}

// with_author loads each row's `author` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q CommentQuery) with_author(configure ...fn (UserQuery) UserQuery) CommentQuery {
	mut next := q
	next.with_author = true
	next.author_fns = configure
	return next
}

