	if 'replies' !in n.loaded {
		return NotLoadedError{
			edge: 'comments.replies'
		}
	}
	return n.replies
}

// query_author starts a query of this row's `author`, which matches
// nothing when the row has none.
pub fn (n CommentNode) query_author() UserQuery {
	key := n.comment.user_id
	return n.graph.users().where(load.eq('id', key))
}

// query_parent starts a query of this row's `parent`, which matches
// nothing when the row has none.
pub fn (n CommentNode) query_parent() CommentQuery {
	key := n.comment.parent_id or { return n.graph.comments().where(load.in_ints('id', [])) }
	return n.graph.comments().where(load.eq('id', key))
}

// query_article starts a query of this row's `article`, which matches
// nothing when the row has none.
pub fn (n CommentNode) query_article() ArticleQuery {
	if !(n.comment.owner_type == 'Article') {
		return n.graph.articles().where(load.in_ints('id', []))
	}
	key := n.comment.owner_id
	return n.graph.articles().where(load.eq('id', key))
}

// query_post starts a query of this row's `post`, which matches
// nothing when the row has none.
pub fn (n CommentNode) query_post() PostQuery {
	if !(n.comment.owner_type == 'Post') {
		return n.graph.posts().where(load.in_ints('id', []))
	}
	key := n.comment.owner_id
	return n.graph.posts().where(load.eq('id', key))
}

// query_replies starts a query of this row's `replies`.
pub fn (n CommentNode) query_replies() CommentQuery {
	return n.graph.comments().where(load.eq('parent_id', n.comment.id), load.is_null('deleted_at'))
}
